import React, { useState } from "react";
import { useNavigate, Navigate } from "react-router-dom";
import { useAuth } from "../context/AuthContext";

export default function AuthPage() {
  const navigate = useNavigate();
  const { user, login, register } = useAuth();

  if (user) return <Navigate to="/dashboard" replace />;

  const [tab, setTab] = useState("register");
  const [loading, setLoading] = useState(false);
  const [msg, setMsg] = useState("");

  const [loginForm, setLoginForm] = useState({ email: "", password: "" });
  const [regForm, setRegForm] = useState({
    first_name: "", last_name: "", email: "",
    phone: "", password: "", national_id: "",
  });

  const handleLogin = async (e) => {
    e.preventDefault();
    setLoading(true); setMsg("");
    try {
      await login(loginForm.email, loginForm.password);
      navigate("/dashboard");
    } catch (err) {
      setMsg(err.response?.data?.message || "Login failed.");
    } finally { setLoading(false); }
  };

  const handleRegister = async (e) => {
    e.preventDefault();
    setLoading(true); setMsg("");
    try {
      await register(regForm);
      navigate("/dashboard");
    } catch (err) {
      setMsg(err.response?.data?.message || "Registration failed.");
    } finally { setLoading(false); }
  };

  const inputStyle = {
    width: "100%", border: "1.5px solid var(--border)", borderRadius: "var(--r-md)",
    padding: "13px 16px", fontFamily: "'Sora',sans-serif", fontSize: 14,
    outline: "none", background: "white", color: "var(--charcoal)",
  };
  const iconInputStyle = { ...inputStyle, paddingLeft: 44 };

  return (
    <div style={{ minHeight: "calc(100vh - var(--nav-h))", display: "grid", gridTemplateColumns: "1fr 1fr" }}>

      {/* ── Left Visual ── */}
      <div style={{
        background: "linear-gradient(145deg,#1C1C1E 0%,#3A2E22 100%)",
        display: "flex", flexDirection: "column", justifyContent: "flex-end",
        padding: 48, position: "relative", overflow: "hidden",
      }}>
        <div style={{ position: "absolute", top: -80, right: -80, width: 320, height: 320, borderRadius: "50%", background: "rgba(200,151,90,.12)" }} />
        <div style={{ position: "absolute", bottom: -40, left: -40, width: 200, height: 200, borderRadius: "50%", background: "rgba(200,151,90,.07)" }} />
        <div style={{ position: "relative", zIndex: 1 }}>
          <span style={{ fontSize: 11, fontWeight: 600, letterSpacing: "1.8px", textTransform: "uppercase", color: "rgba(200,151,90,.8)", marginBottom: 10, display: "block" }}>Welcome to Roomly</span>
          <h2 className="h2" style={{ color: "white", marginBottom: 14 }}>Your next perfect stay is waiting</h2>
          <p style={{ color: "rgba(255,255,255,.6)", fontSize: 15, marginBottom: 28 }}>
            Join thousands of guests on Egypt's most trusted room booking platform.
          </p>
          <div style={{ display: "flex", gap: 24 }}>
            {[["12K+","Rooms listed"],["98%","Satisfaction"],["180+","Cities"]].map(([n,l]) => (
              <div key={l}>
                <div style={{ fontFamily: "'DM Serif Display',serif", fontSize: 22, color: "white" }}>{n}</div>
                <div style={{ fontSize: 12, color: "rgba(255,255,255,.5)" }}>{l}</div>
              </div>
            ))}
          </div>
        </div>
      </div>

      {/* ── Right Form ── */}
      <div style={{ padding: "52px 56px", display: "flex", flexDirection: "column", justifyContent: "center", background: "white", overflowY: "auto" }}>

        {/* Tab switcher */}
        <div style={{ display: "flex", gap: 4, background: "var(--cream)", borderRadius: 999, padding: 4, marginBottom: 28, width: "fit-content" }}>
          {["register","login"].map(t => (
            <button key={t} onClick={() => { setTab(t); setMsg(""); }} style={{
              border: "none", background: tab === t ? "white" : "none",
              fontFamily: "'Sora',sans-serif", fontSize: 13, fontWeight: 500,
              padding: "8px 20px", borderRadius: 999, cursor: "pointer",
              color: tab === t ? "var(--charcoal)" : "var(--muted)",
              boxShadow: tab === t ? "var(--sh-sm)" : "none", transition: "all .15s",
            }}>{t === "register" ? "Create account" : "Sign in"}</button>
          ))}
        </div>

        {msg && (
          <div style={{ background: "var(--coral-lt)", border: "1px solid var(--coral)", borderRadius: "var(--r-sm)", padding: "10px 14px", marginBottom: 16, fontSize: 13, color: "var(--coral)" }}>
            {msg}
          </div>
        )}

        {/* ── Register Form ── */}
        {tab === "register" && (
          <form onSubmit={handleRegister}>
            <span className="sec-label">New account</span>
            <h2 className="h2" style={{ marginBottom: 6 }}>Create your account</h2>
            <p style={{ fontSize: 14, color: "var(--muted)", marginBottom: 22 }}>All fields are required to book rooms.</p>

            <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 14, marginBottom: 18 }}>
              <div>
                <label style={{ display: "block", fontSize: 12, fontWeight: 600, marginBottom: 7 }}>First name</label>
                <input style={inputStyle} placeholder="First Name" value={regForm.first_name}
                  onChange={e => setRegForm(p => ({ ...p, first_name: e.target.value }))} required />
              </div>
              <div>
                <label style={{ display: "block", fontSize: 12, fontWeight: 600, marginBottom: 7 }}>Last name</label>
                <input style={inputStyle} placeholder="Last Name" value={regForm.last_name}
                  onChange={e => setRegForm(p => ({ ...p, last_name: e.target.value }))} required />
              </div>
            </div>

            <div style={{ marginBottom: 18 }}>
              <label style={{ display: "block", fontSize: 12, fontWeight: 600, marginBottom: 7 }}>Email address</label>
              <div style={{ position: "relative" }}>
                <span style={{ position: "absolute", left: 14, top: "50%", transform: "translateY(-50%)", fontSize: 16, color: "var(--muted)" }}>✉️</span>
                <input style={iconInputStyle} type="email" placeholder="you@example.com" value={regForm.email}
                  onChange={e => setRegForm(p => ({ ...p, email: e.target.value }))} required />
              </div>
            </div>

            <div style={{ marginBottom: 18 }}>
              <label style={{ display: "block", fontSize: 12, fontWeight: 600, marginBottom: 7 }}>Phone number</label>
              <div style={{ position: "relative" }}>
                <span style={{ position: "absolute", left: 14, top: "50%", transform: "translateY(-50%)", fontSize: 16, color: "var(--muted)" }}>📱</span>
                <input style={iconInputStyle} type="tel" inputMode="numeric" placeholder="+20 100 000 0000" value={regForm.phone}
                  onChange={e => setRegForm(p => ({ ...p, phone: e.target.value.replace(/\D/g, "").slice(0, 11) }))} required />
              </div>
            </div>

            <div style={{ marginBottom: 18 }}>
              <label style={{ display: "block", fontSize: 12, fontWeight: 600, marginBottom: 7 }}>National ID number</label>
              <input style={inputStyle} placeholder="12345678901234" value={regForm.national_id}
                onChange={e => setRegForm(p => ({ ...p, national_id: e.target.value }))} required />
            </div>

            <div style={{ marginBottom: 18 }}>
              <label style={{ display: "block", fontSize: 12, fontWeight: 600, marginBottom: 7 }}>Password</label>
              <div style={{ position: "relative" }}>
                <span style={{ position: "absolute", left: 14, top: "50%", transform: "translateY(-50%)", fontSize: 16, color: "var(--muted)" }}>🔒</span>
                <input style={iconInputStyle} type="password" placeholder="At least 8 characters" value={regForm.password}
                  onChange={e => setRegForm(p => ({ ...p, password: e.target.value }))} required />
              </div>
            </div>

            <div style={{ display: "flex", gap: 10, alignItems: "flex-start", marginBottom: 20, fontSize: 13, color: "var(--muted)" }}>
              <input type="checkbox" required style={{ marginTop: 3, accentColor: "var(--gold)" }} />
              <span>I agree to Roomly's <a href="#" style={{ color: "var(--gold)" }}>Terms</a> and <a href="#" style={{ color: "var(--gold)" }}>Privacy Policy</a></span>
            </div>

            <button type="submit" disabled={loading} style={{
              width: "100%", background: "var(--charcoal)", color: "white", border: "none",
              borderRadius: 999, padding: "14px", fontFamily: "'Sora',sans-serif",
              fontSize: 15, fontWeight: 500, cursor: "pointer", display: "flex",
              alignItems: "center", justifyContent: "center", transition: "background .18s",
            }}>
              {loading ? "Creating account…" : "Create Account →"}
            </button>
          </form>
        )}

        {/* ── Login Form ── */}
        {tab === "login" && (
          <form onSubmit={handleLogin}>
            <span className="sec-label">Welcome back</span>
            <h2 className="h2" style={{ marginBottom: 6 }}>Sign in</h2>
            <p style={{ fontSize: 14, color: "var(--muted)", marginBottom: 22 }}>
              Don't have an account?{" "}
              <span onClick={() => setTab("register")} style={{ color: "var(--gold)", fontWeight: 600, cursor: "pointer" }}>Register</span>
            </p>

            <div style={{ marginBottom: 18 }}>
              <label style={{ display: "block", fontSize: 12, fontWeight: 600, marginBottom: 7 }}>Email address</label>
              <div style={{ position: "relative" }}>
                <span style={{ position: "absolute", left: 14, top: "50%", transform: "translateY(-50%)", fontSize: 16, color: "var(--muted)" }}>✉️</span>
                <input style={iconInputStyle} type="email" placeholder="you@example.com" value={loginForm.email}
                  onChange={e => setLoginForm(p => ({ ...p, email: e.target.value }))} required />
              </div>
            </div>

            <div style={{ marginBottom: 24 }}>
              <label style={{ display: "block", fontSize: 12, fontWeight: 600, marginBottom: 7 }}>
                Password
                <a href="#" style={{ float: "right", fontSize: 12, color: "var(--gold)", textDecoration: "none", fontWeight: 400 }}>Forgot password?</a>
              </label>
              <div style={{ position: "relative" }}>
                <span style={{ position: "absolute", left: 14, top: "50%", transform: "translateY(-50%)", fontSize: 16, color: "var(--muted)" }}>🔒</span>
                <input style={iconInputStyle} type="password" placeholder="Your password" value={loginForm.password}
                  onChange={e => setLoginForm(p => ({ ...p, password: e.target.value }))} required />
              </div>
            </div>

            <button type="submit" disabled={loading} style={{
              width: "100%", background: "var(--charcoal)", color: "white", border: "none",
              borderRadius: 999, padding: "14px", fontFamily: "'Sora',sans-serif",
              fontSize: 15, fontWeight: 500, cursor: "pointer", display: "flex",
              alignItems: "center", justifyContent: "center", transition: "background .18s",
            }}>
              {loading ? "Signing in…" : "Sign in →"}
            </button>
          </form>
        )}
      </div>
    </div>
  );
}
